/* Planejamento compartilhado da obra. Contratos e preços vêm do painel; baixas nunca são inferidas. */
(function(){
 'use strict';
 const D=window.DiamondPrevisaoDomain,S=window.DiamondPrevisaoStore;
 const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=v=>v==null?'A conferir':(v/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 const decimal=v=>v==null?'':(v/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
 const percentValue=v=>v==null?'':Number((v*100).toFixed(2));
 const pct=v=>v==null?'—':(100*v).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%';
 const day=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 const date=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')?v.split('-').reverse().join('/'):'—';
 const sum=xs=>{if(xs.some(x=>!Number.isSafeInteger(x)))return null;const n=xs.reduce((a,b)=>a+BigInt(b),0n);return n>BigInt(Number.MAX_SAFE_INTEGER)?null:Number(n);};
 const uid=()=>crypto.randomUUID();
 function cents(value){
  const s=String(value||'').trim().replace(/^R\$\s*/, '');
  if(!/^(?:\d+|\d{1,3}(?:\.\d{3})+)(?:,\d{1,2})?$/.test(s))return null;
  const [a,b='']=s.replaceAll('.','').split(','),n=BigInt(a)*100n+BigInt((b+'00').slice(0,2));
  return n>BigInt(Number.MAX_SAFE_INTEGER)?null:Number(n);
 }
 function fraction(value){const s=String(value).trim().replace(',','.');return /^\d+(?:\.\d{1,2})?$/.test(s)?Number(s)/100:null;}
 const table=(headers,rows)=>`<div class="pc-table-wrap" tabindex="0" role="region" aria-label="Tabela com rolagem horizontal"><table class="di-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Nenhum registro.</td></tr>`}</tbody></table></div>`;
 const field=(label,name,value='',extra='')=>`<label>${label}<input name="${name}" value="${e(value)}" ${extra}></label>`;
 const amountField=(label,name,value)=>field(label,name,decimal(value),'inputmode="decimal" placeholder="0,00" autocomplete="off"');
 const note=s=>`<p class="pc-note">${s}</p>`;
 let state,refreshTimer;
 const sessionKey=()=>{const u=STORE.getUser?.();return JSON.stringify([u?.usuario,u?.senhaHash,u?.papel]);};
 const active=current=>!!current&&state===current&&current.root?.isConnected&&current.route===location.hash&&current.session===sessionKey()&&STORE.podeVerPainel();
 function assertActive(current){if(!active(current))throw Error('Esta edição pertence a uma tela ou sessão anterior. Abra a previsão novamente para continuar.');}
 function finance(data){
  const contracts={};
  for(const [id,c] of Object.entries(data.contracts)){
   const receipts=data.receipts.filter(r=>r.unitId===id&&r.contractKey===c.contractKey);
   contracts[id]={...c,receivedCommonCents:c.receiptsReviewed?sum(receipts.filter(r=>r.natureza==='comum').map(r=>r.valorCents)):null,receivedFinalCents:c.receiptsReviewed?sum(receipts.filter(r=>r.natureza==='final').map(r=>r.valorCents)):null};
  }
  return {contributionsCents:data.contributionsReviewed?sum(data.contributions.map(c=>c.valorCents)):null,contracts};
 }
 function model(settings=state.record.data.settings,data=state.record.data){
  // A failed conditions query cannot be interpreted as an empty sales portfolio.
  const base=D.build({rows:state.x.unitsOk&&state.x.conditionsOk&&!state.x.insights.duplicadas?.length?state.x.insights.rows:null,settings:{...settings,selectedInventoryIds:[...state.selected]},finance:finance(data)});return window.DiamondCoberturaDomain?.consolidate(base,data.coverageConsolidation)||base;
 }
 const metricKeys={'Custo previsto da obra':'target','Vendas brutas':'gross','Aportes realizados':'contributions','Permutas':'barter','Cobertura contratada':'coverage','Falta cobrir':'shortfall','Meta de novas vendas':'requiredGross','Comissões das vendas':'commission','Vendas líquidas':'net','Parcelas finais contratadas':'finals','Aportes + recebido comum':'receivedWithContributions','Recebido durante a obra':'receivedCommon','A receber durante a obra':'outstandingCommon','Parcelas comuns contratadas':'commonInstallments','Final já recebida':'receivedFinal','Final ainda a receber':'outstandingFinal','Estoque em tabela':'inventoryGross','Cobertura potencial':'inventoryCoverage','Selecionado para vender':'selectionGross','Falta após a seleção':'selectionGap'};
 function coverageModel(m){const api=window.DiamondCoberturaDomain;if(!api)return null;const classifications={...(state.x.classifications||{})};for(const c of m.contracts)if(!classifications[c.id]){const origin=api.classifyOrigin?.(c.row.contrato,c.row.u.unidade);if(origin)classifications[c.id]=origin;}return api.build({model:m,classifications});}
 function prepareDetails(m){
  const c=coverageModel(m),details={},target=m.settings.targetCents;
  const add=(key,title,cents,formula,source,rows=[],extra={})=>{details[key]={key,title,cents,knownCents:cents,complete:cents!==null,percent:target>0&&cents!==null?cents/target:null,knownPercent:null,formula,source,rows,...extra};};
  const contractRows=(read,ids)=>m.contracts.filter(v=>!ids||ids.includes(v.id)).map(v=>({id:v.id,origin:'Unidade '+v.row.u.unidade,description:v.row.nome||'Cliente a conferir',cents:read(v),note:v.coverageComplete?'Contrato atual e conferência financeira':'Contrato com dados a conferir'}));
  const contributionRows=state.record.data.contributions.map(v=>({origin:'Aporte · '+date(v.data),description:v.socio,cents:v.valorCents,note:(m.contributionsCents===null?'Aportes a conferir. ':'Aporte realizado conferido. ')+(v.observacao||'')}));
  add('target','Custo previsto da obra',target,'Meta de recursos configurada para a obra.','Premissas da Previsão de custo',[{origin:'Empreendimento',description:'Custo previsto',cents:target,note:'Meta configurável; não é gasto realizado.'}]);
  const definitions=[['gross','Vendas brutas','grossCents','Soma dos valores contratuais das vendas atuais.'],['barter','Permutas','permutaCents','Soma dos bens e serviços em permuta incluídos nos contratos. Não é recebimento em dinheiro.'],['commission','Comissões das vendas','commissionCents','Soma das comissões totais conferidas de cada venda. Dedução feita uma única vez.'],['finals','Parcelas finais contratadas','finalCents','Soma das séries finais identificadas na conferência. Ficam fora da cobertura da obra.'],['receivedCommon','Recebido durante a obra','receivedCommonCents','Baixas comuns confirmadas para a revisão atual dos contratos. Antes de comissões e gastos.'],['receivedFinal','Final já recebida','receivedFinalCents','Baixas finais confirmadas. Mesmo recebidas, permanecem fora da cobertura.']];
  for(const [key,title,prop,formula]of definitions)add(key,title,m.totals[prop],formula,key.startsWith('received')?'Recebimentos registrados e conferidos na Previsão de custo':'Condições atuais e conferência financeira das vendas',contractRows(v=>v[prop]),c?.metrics[key]||{});
  add('contributions','Aportes realizados',m.contributionsCents,'Soma dos aportes realizados e conferidos. Aportes não classificam vendas como SCP.','Lançamentos de aportes da Previsão de custo',contributionRows,c?.metrics.contributions||{});
  add('coverage','Cobertura contratada',m.totals.coverageCents,'Aportes + vendas brutas − comissões − parcelas finais. Permutas já estão incluídas nas vendas.','Contratos e aportes conferidos; inclui recebimentos futuros',[...contributionRows,...contractRows(v=>v.contributionCents)],c?.coverage||{knownCents:m.totals.coverageKnownCents});
  add('shortfall','Falta cobrir',m.totals.shortfallCents,'Máximo entre zero e custo previsto menos cobertura contratada.','Meta configurada e cobertura dos contratos',[],c?.metrics.shortfall||{});
  add('requiredGross','Meta de novas vendas',m.future.requiredGrossCents,'Falta cobrir ÷ (percentual durante a obra − comissão futura). Arredondamento para cima em centavos.','Premissas para novas vendas; não altera contratos existentes',[],c?.metrics.requiredGross||{});
  const total=(a,b)=>a!==null&&b!==null?a-b:null;
  add('net','Vendas líquidas',total(m.totals.grossCents,m.totals.commissionCents),'Venda bruta menos comissão; inclui parcelas finais e permutas.','Condições atuais e comissões conferidas',contractRows(v=>total(v.grossCents,v.commissionCents)));
  add('outstandingCommon','A receber durante a obra',m.totals.receivedComplete?sum(m.contracts.map(v=>v.outstandingCommonCents)):null,'Valor comum em dinheiro contratado menos baixas comuns conferidas.','Contratos atuais e recebimentos conferidos',contractRows(v=>v.outstandingCommonCents));
  add('outstandingFinal','Final ainda a receber',m.totals.receivedComplete?sum(m.contracts.map(v=>v.outstandingFinalCents)):null,'Parcelas finais contratadas menos baixas finais conferidas.','Contratos atuais e recebimentos conferidos',contractRows(v=>v.outstandingFinalCents));
  add('receivedWithContributions','Aportes + recebido comum',m.contributionsCents!==null&&m.totals.receivedCommonCents!==null?sum([m.contributionsCents,m.totals.receivedCommonCents]):null,'Aportes realizados + recebimentos comuns confirmados. Não desconta gastos nem comissões pagas.','Aportes e recebimentos conferidos na Previsão de custo',[...contributionRows,...contractRows(v=>v.receivedCommonCents)]);
  add('commonInstallments','Parcelas comuns contratadas',total(m.totals.installmentsCents,m.totals.finalCents),'Séries parceladas menos as finais. Não inclui entradas; valor antes das baixas.','Séries das condições de venda atuais',contractRows(v=>total(v.installmentsCents,v.finalCents)));
  if(c){
   const labels={contributions:'Aportes realizados',direta:'Compra e venda · dinheiro',scp:'SCP · dinheiro',unknown:'Sem classificação · dinheiro',barter:'Permutas',commission:'Comissões · dedução'};
   for(const part of c.decomposition.parts){const prop=part.key==='barter'?'permutaCents':part.key==='commission'?'commissionCents':'commonReceivableCents';add('part-'+part.key,labels[part.key],part.cents,part.key==='contributions'?'Aportes realizados conferidos, separados dos contratos SCP.':part.key==='commission'?'Comissões dos contratos aceitos, subtraídas uma única vez.':part.key==='barter'?'Permutas dos contratos aceitos, contadas uma única vez.':'Valor bruto − permutas − finais dos contratos desta origem. Comissão demonstrada à parte.','Somente contratos com cobertura conferida; origem por declaração explícita no contrato',part.key==='contributions'?contributionRows:contractRows(v=>v[prop],part.unitIds),part);}
   const sim=c.simulation,unitRows=(units,field='priceCents')=>units.map(u=>({id:u.id,origin:'Unidade '+(u.unidade||u.row.u.unidade),description:u.row.nome||'Disponível',cents:u[field],note:field==='contributionCents'?'Cobertura simulada; preço vigente: '+money(u.priceCents):'Preço vigente; cobertura simulada: '+money(u.contributionCents)}));
   const definitions=[['inventoryGross','Estoque em tabela',sim.availableGrossCents,'Soma do preço vigente somente dos apartamentos disponíveis.',sim.apartments],['inventoryCoverage','Cobertura potencial',sim.availableContributionCents,'Preço vigente × (durante a obra − comissão futura), por apartamento.',sim.apartments],['selectionGross','Selecionado para vender',sim.selection.grossCents,'Soma do preço vigente dos apartamentos selecionados. Não reserva nem altera unidades.',sim.apartments.filter(u=>u.selected)],['selectionGap','Falta após a seleção',sim.selection.remainingGapCents,'Falta da simulação menos a cobertura dos apartamentos selecionados; mínimo zero.',sim.apartments.filter(u=>u.selected)],['averagePrice','Preço médio disponível',sim.averagePriceCents,'Soma dos preços dos apartamentos disponíveis ÷ quantidade com preço. Média apenas estimativa.',sim.apartments],['averageContribution','Cobertura média por apartamento',sim.averageContributionCents,'Soma das coberturas calculadas e arredondadas por apartamento ÷ quantidade disponível. A estimativa de quantidade usa a fração exata, sem arredondar a média antes.',sim.apartments],['selectionContribution','Cobertura da seleção',sim.selection.contributionCents,'Soma da cobertura calculada para cada apartamento selecionado.',sim.apartments.filter(u=>u.selected)],['selectionSurplus','Superávit da seleção',sim.selection.surplusCents,'Cobertura da seleção menos a falta da simulação; mínimo zero.',sim.apartments.filter(u=>u.selected)]];
   for(const[key,title,value,formula,units]of definitions){const isPrice=['inventoryGross','selectionGross','averagePrice'].includes(key);add(key,title,value,formula,'Simulação com apartamentos disponíveis, sem loja nem reservados',unitRows(units,isPrice?'priceCents':'contributionCents'),{valueLabel:isPrice?'Preço de tabela':'Cobertura por unidade'});}
   add('estimatedCount','Apartamentos estimados',sim.estimatedCount,'Falta ÷ contribuição média por apartamento, arredondada para cima. A seleção real pode exigir outra quantidade.','Estimativa pela média; confira os preços e unidades na seleção',unitRows(sim.apartments,'contributionCents'),{isQuantity:true,percent:null,valueLabel:'Cobertura por unidade'});
   add('shopInventory','Loja disponível',sum(sim.shops.map(u=>u.priceCents)),'Preço vigente da loja, separado da quantidade e da cobertura simulada dos apartamentos.','Estoque comercial; fora da seleção residencial',unitRows(sim.shops));
  }
  if(m.consolidation?.valid){
   const con=m.consolidation,groupRows=groups=>groups.map(g=>({origin:g.label,description:g.unitIds.map(id=>m.contracts.find(v=>v.id===id)?.row.u.unidade||id).join(', '),cents:g.commonCents,note:g.source}));
   const cashRows=groupRows(con.groups.filter(g=>g.commonCents>0));
   const barterRows=contractRows(v=>v.permutaCents,con.coveredContractIds).filter(r=>r.cents>0),commissionRows=contractRows(v=>v.commissionCents,con.coveredContractIds).map(r=>({...r,cents:-r.cents}));
   Object.assign(details.coverage,{formula:'Aportes + totais monetários consolidados + permutas − comissões. Balões finais separados; recebimentos não são somados novamente.',source:con.source+' · Data-base '+date(con.asOf),rows:[...contributionRows,...cashRows,...barterRows,...commissionRows]});
   for(const part of c.decomposition.parts){const d=details['part-'+part.key];if(part.key==='contributions')continue;Object.assign(d,{formula:part.key==='barter'?'Total integral das permutas cadastradas, contado uma única vez.':part.key==='commission'?'Total de comissões das vendas; dedução única.':'Total monetário consolidado, excluídas permutas e balões finais. Não depende da data de recebimento.',source:con.source+' · Data-base '+date(con.asOf),rows:part.key==='barter'?barterRows:part.key==='commission'?contractRows(v=>v.commissionCents,con.coveredContractIds):groupRows(part.groups||[])});}
   for(const g of con.groups){
    add('consolidated-'+g.id,g.label+' · durante a obra',g.commonCents,'Soma dos valores em dinheiro contratados para a obra, sem permutas nem balão final.',g.source,groupRows([g]));
    if(g.receivedCents!==null){
     const row={origin:g.label,description:'Posição financeira consolidada em '+date(con.asOf),note:'Sem rateio por apartamento e sem gerar baixas individuais.'};
     add('received-'+g.id,g.label+' · recebido',g.receivedCents,'Recebido informado na posição consolidada; já incluído no total da cobertura.',g.source,[{...row,cents:g.receivedCents}]);
     add('outstanding-'+g.id,g.label+' · a vencer',g.outstandingCents,'Total monetário consolidado menos recebido.',g.source,[{...row,cents:g.outstandingCents}]);
    }
   }
  }
  state.presentation={model:m,coverage:c,details};return c;
 }
 function metric(label,value,sub,style='',id='',detailKey=''){
  const key=detailKey||metricKeys[label],detail=state.presentation?.details[key],shown=String(value).replace(/^R\$([\s\u00a0]+)/,'<span class="pc-currency">R$</span>$1');
  const percentage=detail&&!detail.isQuantity?(detail.percent!==null&&detail.percent!==undefined?pct(detail.percent)+' do custo':detail.knownPercent!==null&&detail.knownPercent!==undefined?pct(detail.knownPercent)+' do custo · parcial conhecido':'Percentual a conferir'):'';
  return `<button type="button" class="pc-metric pc-metric-button ${style}${value==='A conferir'?' pc-unknown':''}" data-pc-detail="${e(key||'coverage')}" aria-haspopup="dialog"><span>${label}</span><strong ${id?`data-pc-value="${id}"`:''}>${shown}</strong>${percentage?`<span class="pc-metric-percent">${e(percentage)}</span>`:''}<small>${sub}</small><span class="pc-metric-link">Ver composição <span aria-hidden="true">↗</span></span></button>`;
 }
 function originBreakdown(c){if(!c)return '';const d=c.decomposition,labels={contributions:'Aportes',direta:'Compra e venda · dinheiro',scp:'SCP · dinheiro',unknown:'A classificar · dinheiro',barter:'Permutas',commission:'Comissões'};
  return `<section class="pc-origin-section" aria-label="Origem da cobertura"><div class="pc-section-title"><div><h2>De onde vem a cobertura</h2><p>Parcelas finais excluídas. Dinheiro, permutas e aportes separados; comissão deduzida uma vez.</p></div></div><div class="pc-origin-grid">${d.parts.filter(part=>part.key!=='commission').map(part=>{const amount=part.complete?part.cents:part.knownCents,ratio=part.complete?part.percent:part.knownPercent,negative=part.sign<0&&amount>0,rows=state.presentation.details['part-'+part.key]?.rows||[],count=part.groups?.length?new Set(part.groups.flatMap(g=>g.unitIds)).size:part.key==='contributions'?rows.length:rows.filter(r=>r.cents>0).length;return `<button type="button" class="pc-origin-card pc-origin-${e(part.key)}" data-pc-detail="part-${e(part.key)}" aria-haspopup="dialog"><span>${labels[part.key]}</span><strong>${negative?'− ':''}${money(amount).replace(/^R\$([\s\u00a0]+)/,'<span class="pc-currency">R$</span>$1')}</strong><small>${ratio==null?'Percentual a conferir':(negative?'− ':'')+pct(Math.abs(ratio))+' do custo'}${part.complete?'':' · identificado'}</small><span class="pc-origin-track" aria-hidden="true"><i style="width:${ratio==null?0:Math.min(100,Math.max(0,Math.abs(ratio)*100))}%"></i></span><span class="pc-origin-detail">${count} ${part.key==='contributions'?'aporte(s)':'unidade(s) com valor'} · Ver detalhe ↗</span></button>`;}).join('')}</div><button type="button" class="di-btn pc-commission-cost" data-pc-detail="part-commission">Comissões das vendas contratadas: custo deduzido de ${money(c.metrics.commission.cents)} · Ver detalhe ↗</button>${!d.classificationComplete?note('Há vendas sem classificação de origem. Elas aparecem separadas e não são presumidas como vendas diretas.'):''}${!d.complete?'<p class="pc-warning">Composição parcial: apenas os contratos aceitos e aportes conferidos entram nos valores identificados. Revise as pendências para fechar o total.</p>':''}</section>`;
 }
 function compositionTable(m,c){
  const con=m.consolidation?.valid?m.consolidation:null,target=m.settings.targetCents,rows=[];
  const add=(label,value,key)=>rows.push({label,value,key});
  if(con){
   for(const g of con.groups.filter(g=>g.origin==='scp'&&!g.additional))add(g.label+' — total consolidado',g.commonCents,'consolidated-'+g.id);
   add('Permutas — total cadastrado',con.barterCents,'part-barter');
   for(const g of con.groups.filter(g=>g.origin!=='scp'&&g.origin!=='barter'&&!g.additional))add(g.label+' — parcelas durante a obra',g.commonCents,'consolidated-'+g.id);
   for(const g of con.groups.filter(g=>g.additional&&g.commonCents>0))add(g.label+' — dinheiro durante a obra',g.commonCents,'consolidated-'+g.id);
   add('Aportes dos sócios',m.contributionsCents,'contributions');
   if(con.commissionCents>0)add('Comissões — dedução',-con.commissionCents,'part-commission');
  }else{
   const labels={scp:'SCP — dinheiro',direta:'Compra e venda — dinheiro',unknown:'Vendas — origem a classificar',barter:'Permutas',contributions:'Aportes dos sócios',commission:'Comissões — dedução'};
   for(const p of c.decomposition.parts)if(p.knownCents!==0||p.key==='contributions')add(labels[p.key],p.knownCents===null?null:p.sign*p.knownCents,'part-'+p.key);
  }
  const tr=(r,cls='')=>`<tr class="${cls}"><th scope="row"><button type="button" data-pc-detail="${e(r.key)}" aria-haspopup="dialog">${e(r.label)} <span aria-hidden="true">↗</span></button></th><td>${money(r.value)}</td><td>${target>0&&r.value!==null?pct(r.value/target):'—'}</td></tr>`;
  return `<section class="pc-projection pc-composition" aria-label="Composição da cobertura"><div class="pc-section-title"><div><h2>Composição da cobertura</h2><p>Veja quanto cada origem cobre do custo da obra. Clique na linha para consultar a composição.</p></div><span class="pc-tag">Atualiza com as vendas</span></div><div class="pc-composition-scroll"><table><thead><tr><th scope="col">Origem</th><th scope="col">Cobertura da obra</th><th scope="col">% do custo</th></tr></thead><tbody>${rows.map(r=>tr(r)).join('')}</tbody><tfoot>${tr({label:m.totals.coverageComplete?'Total de cobertura':'Cobertura confirmada até agora',value:m.totals.coverageKnownCents,key:'coverage'},'pc-composition-total')}${tr({label:m.totals.coverageComplete?'Falta cobrir':'Falta sobre o valor confirmado',value:m.totals.shortfallKnownCents,key:'shortfall'},'pc-composition-gap')}</tfoot></table></div>${note('Novas vendas com condições completas entram automaticamente. Permutas são contadas uma vez; parcelas finais ficam separadas. Recebimentos não são somados novamente.')}${con?.pending?.length?`<p class="pc-warning">${con.pending.length} nova(s) venda(s) ainda com dados pendentes, fora da soma acima. <button type="button" class="di-btn" data-pc-open-section="contracts">Completar condições</button></p>`:''}${con?.additionalUnitIds?.length?note(con.additionalUnitIds.length+' nova(s) venda(s) incorporada(s) após a consolidação inicial.'):''}</section>`;
 }
 function consolidatedSales(m){if(!m.consolidation?.valid)return '';const con=m.consolidation;return `<section class="pc-projection" aria-label="Parcelamentos consolidados"><h2>Vendas parceladas durante a obra</h2><div class="pc-breakdown">${con.groups.filter(g=>g.origin==='direta').map(g=>metric(e(g.label),money(g.commonCents),'Parcelas somadas; permuta e balão separados','','','consolidated-'+g.id)).join('')}</div>${note('Base consolidada em '+date(con.asOf)+'. Novas vendas usam as condições atuais; os valores individuais permanecem preservados.')}${con.adjustmentCents?note('Diferença documental em relação aos valores individuais: '+money(con.adjustmentCents)+'. Detalhes e fontes nos cards; nenhum contrato foi ajustado para forçar a soma.'):''}</section>`;}
 function consolidatedCash(m){if(!m.consolidation?.valid)return '';return m.consolidation.groups.filter(g=>g.receivedCents!==null).map(g=>`<section class="pc-projection"><h3>${e(g.label)} · posição de recebimentos</h3>${note('Data-base '+date(m.consolidation.asOf)+'. Esta divisão não altera a cobertura contratada e não é somada às baixas por unidade.')}<div class="pc-breakdown">${metric(e(g.label)+' · total',money(g.commonCents),'Total monetário contratado','','','consolidated-'+g.id)}${metric(e(g.label)+' · recebido',money(g.receivedCents),g.receivedCount==null?'Recebimento consolidado':g.receivedCount+' parcelas recebidas','','','received-'+g.id)}${metric(e(g.label)+' · a vencer',money(g.outstandingCents),g.outstandingCount==null?'Saldo consolidado':g.outstandingCount+' parcelas a vencer','','','outstanding-'+g.id)}</div></section>`).join('');}
 function finalsBanner(m,c){const metric=c?.metrics.finals;return `<button type="button" class="pc-finals-strip" data-pc-detail="finals" aria-haspopup="dialog"><span><b>Parcelas finais contratadas</b><small>Fora da cobertura da obra, mesmo quando recebidas.</small></span><span><strong>${money(m.totals.finalCents)}</strong><small>${metric?.percent!=null?pct(metric.percent)+' do custo':metric?.knownPercent!=null?pct(metric.knownPercent)+' do custo · parcial conhecido':'Percentual a conferir'} · Ver detalhe ↗</small></span></button>`;}
 function apartmentGoal(m,c){
  if(!c)return '';const i=c.simulation,r=m.future;
  return `<section class="pc-apartment-goal" aria-label="Apartamentos para cobrir a obra"><button type="button" class="pc-apartment-count" data-pc-detail="estimatedCount" aria-haspopup="dialog"><span>FALTAM VENDER · ESTIMATIVA</span><strong>${i.estimatedCount==null?'—':i.estimatedCount}</strong><b>apartamentos para cobrir a obra</b><small>Pela média dos apartamentos disponíveis · Ver cálculo ↗</small></button><div class="pc-apartment-assumptions"><h3>Quanto cada nova venda cobre</h3><p><b>${pct(r.P)}</b> durante a obra − <b>${pct(r.C)}</b> de comissão = <strong>${r.valid?pct(r.P-r.C):'—'} líquidos</strong> para a obra.</p><p>Os ${r.P==null?'—':pct(1-r.P)} da parcela final ficam fora dessa cobertura.</p><p>Preço médio: <b>${money(i.averagePriceCents)}</b> · Cobertura líquida por apartamento: <b>${money(i.averageContributionCents)}</b></p>${i.insufficient?`<p class="pc-warning">O estoque de ${i.availableCount} apartamentos não cobre toda a falta com estas premissas. Ainda faltariam ${money(i.remainingGapCents)} após vender todos.</p>`:''}${i.partial?'<p class="pc-warning">Estimativa parcial: há dados pendentes na cobertura.</p>':''}<div class="pc-goal-actions"><button type="button" class="di-btn primary" data-pc-goal-preset>Simular 50% durante a obra, 50% final e 5% comissão</button><button type="button" class="di-btn" data-pc-open-section="settings">Ajustar percentuais ↓</button></div></div></section>`;
 }
 function summary(m){
  const coverage=prepareDetails(m);
  const t=m.totals,target=m.settings.targetCents,ratio=target>0&&t.coverageCents!==null?t.coverageCents/target:null;
  const excess=t.coverageCents!==null&&target!==null?Math.max(0,t.coverageCents-target):null;
  const soldNet=t.grossCents!==null&&t.commissionCents!==null?t.grossCents-t.commissionCents:null;
  const outstanding=t.receivedComplete?sum(m.contracts.map(c=>c.outstandingCommonCents)):null;
  const finalOutstanding=t.receivedComplete?sum(m.contracts.map(c=>c.outstandingFinalCents)):null;
  const issues=m.issues.filter(i=>i.scope==='coverage'||i.scope==='target'),messages=[...new Set(issues.map(i=>i.message))];
  return `<div class="pc-summary-heading"><div><p class="pc-eyebrow">POSIÇÃO DO EMPREENDIMENTO</p><h2>Panorama financeiro</h2></div><span class="pc-summary-status ${t.coverageComplete?'is-complete':'is-pending'}">${t.coverageComplete?'Cobertura conferida':'Previsão parcial · conferir dados'}</span></div>
  <div class="pc-kpis">${metric('Custo previsto da obra',money(target),'Meta configurável','pc-dark','target')}${metric('Aportes realizados',money(m.contributionsCents),'Independentes da SCP','pc-received','','contributions')}${metric('Cobertura contratada',money(t.coverageCents),'Inclui permutas e recebimentos futuros','pc-accent','coverage')}${metric('Falta cobrir',money(t.shortfallCents),ratio===null?'Conclua as conferências abaixo':'Custo menos cobertura contratada','','shortfall')}</div>
  ${apartmentGoal(m,coverage)}
  <section class="pc-projection" aria-label="Cobertura e meta de vendas"><div class="pc-section-title"><div><h2>Cobertura e meta de vendas</h2><p>O que já está contratado e o que falta para cobrir a obra.</p></div><button type="button" class="di-btn" data-pc-open-section="contracts">Conferir contratos ↓</button></div>
  <div class="pc-sales-goal">${metric('Meta de novas vendas',money(m.future.requiredGrossCents),`${pct(m.future.P)} durante a obra · ${pct(m.future.C)} comissão`,'pc-dark','sales-goal')}<div class="pc-goal-description"><b>Quanto ainda precisa ser vendido</b><p>Somente a parte durante a obra, depois da comissão, cobre a meta. A parcela final fica de fora.</p><button type="button" class="di-btn" data-pc-open-section="settings">Editar premissas ↓</button></div></div>
  <div class="pc-progress"><div><b>${ratio===null?'Cobertura a conferir':pct(ratio)+' do custo coberto'}</b><span>${excess>0?'Excedente previsto: '+money(excess):'Parcelas finais fora da cobertura'}</span></div>${ratio===null?'<div class="pc-progress-unknown">Percentual disponível após conferir a cobertura.</div>':`<progress max="100" value="${Math.max(0,Math.min(100,ratio*100))}" aria-label="Percentual de cobertura da obra"></progress>`}${note('Cobertura inclui permutas e recebimentos futuros contratados. Não representa saldo bancário nem disponibilidade imediata de dinheiro.')}</div>
  ${issues.length||!m.future.valid?`<div class="pc-warning pc-summary-warning" role="status"><div class="pc-warning-heading"><div><b>Existem dados a conferir antes de fechar a meta.</b>${issues.length?`<span>Subtotal identificado: ${money(t.coverageKnownCents)}. Não é a cobertura total.</span>`:''}</div><button type="button" class="di-btn" data-pc-open-section="editing">Editar e conferir ↓</button></div>${messages.length?`<details class="pc-issue-details" data-section="coverage-issues"><summary>Ver ${messages.length} assunto(s) a conferir</summary><ul>${messages.map(text=>`<li>${e(text)}</li>`).join('')}</ul></details>`:''}${!m.future.valid?'<p>Informe a comissão futura (inclusive 0%) e um percentual durante a obra maior que a comissão. A soma durante a obra + final deve ser 100%.</p>':''}</div>`:''}</section>
  ${originBreakdown(coverage)}${compositionTable(m,coverage)}${consolidatedSales(m)}${finalsBanner(m,coverage)}<details class="pc-details" data-section="sales-composition"><summary>Composição das vendas <span>Comissões, vendas líquidas e parcelas finais</span></summary><section class="pc-financial-summary" aria-label="Composição financeira"><div class="pc-section-title"><div><h2>Composição das vendas</h2><p>Os mesmos contratos, com comissões e parcelas finais separados.</p></div></div><div class="pc-breakdown">${metric('Vendas brutas',money(t.grossCents),'Valores dos contratos atuais')}${metric('Aportes realizados',money(m.contributionsCents),'Conferidos nos lançamentos do sistema')}${metric('Permutas',money(t.permutaCents),'Já incluídas nas vendas e na cobertura','pc-barter')}${metric('Comissões das vendas',money(t.commissionCents),'Descontadas uma única vez')}${metric('Vendas líquidas',money(soldNet),'Bruto menos comissão; inclui finais')}${metric('Parcelas finais contratadas',money(t.finalCents),'Excluídas da cobertura da obra','pc-final')}</div></section></details>
  <details class="pc-details" data-section="cash"><summary>Recebido e a receber <span>Posições financeiras separadas da cobertura</span></summary>${consolidatedCash(m)}<details class="pc-details"><summary>Baixas individuais por contrato <span>Conferência interna por parcela</span></summary><div class="pc-breakdown">${metric('Aportes + recebido comum',money(m.contributionsCents!==null&&t.receivedCommonCents!==null?sum([m.contributionsCents,t.receivedCommonCents]):null),'Entradas realizadas; antes de comissões e gastos')}${metric('Recebido durante a obra',money(t.receivedCommonCents),'Entradas e parcelas comuns; bruto das baixas')}${metric('A receber durante a obra',money(outstanding),'Saldo de entradas e parcelas comuns')}${metric('Parcelas comuns contratadas',money(t.installmentsCents!==null&&t.finalCents!==null?t.installmentsCents-t.finalCents:null),'Total antes das baixas; não inclui entrada')}${metric('Final já recebida',money(t.receivedFinalCents),'Permanece fora da cobertura','pc-final')}${metric('Final ainda a receber',money(finalOutstanding),'Permanece fora da cobertura','pc-final')}</div>${note(t.receivedComplete?'Recebimentos conferidos para todos os contratos. Entradas e parcelas não são somadas novamente à cobertura.':'Conclua a conferência de recebimentos de cada contrato. Ausência de baixas não confirma que nada foi recebido.')}</details></details>`;
 }
 function inventory(m){
  const c=state.presentation?.model===m?state.presentation.coverage:prepareDetails(m);if(!c)return '<p class="pc-warning">O simulador está indisponível. Atualize a página para carregar os cálculos; seus lançamentos permanecem preservados.</p>';
  const i=c.simulation,r=i.rates,selection=i.selection;
  return `<div class="pc-section-title"><div><p class="pc-eyebrow">PLANEJE AS PRÓXIMAS VENDAS</p><h2>Quanto o estoque pode cobrir</h2><p>Somente apartamentos disponíveis, pelo preço vigente. Reservadas e loja ficam de fora da simulação.</p></div><span class="pc-tag">${i.availableCount} apartamento(s) disponíveis</span></div>
  <div class="pc-simulation-rates"><div><span>Durante a obra <b>${pct(r.P)}</b></span><span>Parcela final excluída <b>${r.P==null?'A conferir':pct(1-r.P)}</b></span><span>Comissão futura <b>${r.C==null?'A conferir':pct(r.C)}</b></span></div><button class="di-btn" type="button" data-pc-open-section="settings">Editar percentuais ↓</button></div>
  ${i.partial?'<p class="pc-warning">Simulação parcial, usando somente a cobertura identificada. Quantidade e saldo podem mudar quando as pendências forem conferidas.</p>':''}
  ${!r.valid?'<p class="pc-warning">Informe a comissão futura, inclusive quando for 0%, e um percentual durante a obra maior que a comissão para calcular a quantidade.</p>':''}
  <div class="pc-breakdown pc-simulation-metrics">${metric('Estoque em tabela',money(i.availableGrossCents),'Somente apartamentos disponíveis','','','inventoryGross')}${metric('Cobertura potencial',money(i.availableContributionCents),'Valor que esse estoque pode cobrir','','','inventoryCoverage')}${metric('Apartamentos estimados',i.estimatedCount==null?'A conferir':String(i.estimatedCount),'Estimativa pela média; confirme na seleção real','pc-accent','','estimatedCount')}${metric('Selecionado para vender',money(selection.grossCents),selection.count+' apartamento(s) selecionados','','','selectionGross')}${metric('Cobertura da seleção',money(selection.contributionCents),'Seleção real × percentuais acima','','','selectionContribution')}${metric('Falta após a seleção',money(selection.remainingGapCents),selection.surplusCents>0?'Superávit da seleção: '+money(selection.surplusCents):selection.coversGap===true?'Seleção suficiente para a falta simulada':'Confira preços e apartamentos selecionados','','','selectionGap')}</div>
  <div class="pc-simulation-average"><button type="button" data-pc-detail="averagePrice" aria-haspopup="dialog">Preço médio: <b>${money(i.averagePriceCents)}</b> <span aria-hidden="true">↗</span></button><button type="button" data-pc-detail="averageContribution" aria-haspopup="dialog">Cobertura média: <b>${money(i.averageContributionCents)}</b> <span aria-hidden="true">↗</span></button>${selection.surplusCents>0?`<button type="button" data-pc-detail="selectionSurplus" aria-haspopup="dialog">Superávit: <b>${money(selection.surplusCents)}</b> <span aria-hidden="true">↗</span></button>`:''}</div>
  ${i.insufficient?`<p class="pc-warning">O estoque disponível não cobre a falta simulada com esses percentuais. ${i.possibleCount!=null?'Há '+i.possibleCount+' apartamento(s) disponíveis para essa estimativa. ':''}Revise custo, aportes ou condições das novas vendas.</p>`:''}
  ${!i.inventoryComplete?note('Há informações de preço, percentuais ou disponibilidade a conferir. A média e a estimativa não tratam esses dados como zero.'):''}
  <details class="pc-details" data-section="inventory"><summary>Selecionar unidades para simular a meta <span>${selection.count} apartamento(s) selecionados · não reserva unidades</span></summary>${note('Marque os apartamentos para comparar a seleção real com a quantidade estimada pela média.')}<p class="pc-mobile-table-hint">Deslize para ver todas as colunas.</p>${table(['Simular','Unidade','Preço de tabela','Cobertura prevista'],i.apartments.map(u=>[`<input type="checkbox" data-pc-stock="${e(u.id)}" aria-label="Selecionar unidade ${e(u.unidade||u.row.u.unidade)}" ${u.selected?'checked':''}>`,e(u.unidade||u.row.u.unidade),money(u.priceCents),money(u.contributionCents)]))}</details>
  ${i.shops.length?`<details class="pc-details" data-section="shop-inventory"><summary>Loja separada <span>${i.shops.length} unidade(s) · fora da estimativa de apartamentos</span></summary>${table(['Unidade','Preço vigente','Situação'],i.shops.map(u=>[e(u.unidade||u.row.u.unidade),money(u.priceCents),'Disponível · fora da seleção residencial']))}<button type="button" class="di-btn" data-pc-detail="shopInventory" aria-haspopup="dialog">Conferir valor da loja ↗</button></details>`:''}`;
 }
 function contracts(m){
  return `<details class="pc-details" data-section="contracts" id="pc-contracts-section"><summary>Conferir contratos <span>${m.consolidation?.valid?'Cobertura consolidada · detalhes financeiros por unidade':m.contracts.filter(c=>c.coverageComplete).length+'/'+(m.contracts.length+m.unconfirmedContracts.length)+' completos para cobertura'}</span></summary>${table(['Unidade','Venda bruta','Comissão','Final excluída','Cobertura da venda','Conferência'],[...m.contracts.map(c=>[e(c.row.u.unidade),money(c.grossCents),money(c.commissionCents),money(c.finalCents),money(c.contributionCents),`<button type="button" class="di-btn" data-pc-contract="${e(c.id)}">${c.coverageComplete?'Revisar':'Conferir'}</button><small>${c.receiptsComplete?'Recebimentos conferidos':'Recebimentos a conferir'}</small>`]),...m.unconfirmedContracts.map(c=>[e(c.row.u.unidade),'A conferir','—','—','—',`<button type="button" class="di-btn" data-pc-source="${e(c.id)}">Revisar condições</button><small>Contrato pendente ou revisão desatualizada</small>`])])}${note('Cada venda usa seu valor original e sua comissão total. Identifique explicitamente as séries finais. Alterações do contrato exigem nova conferência. Os percentuais da simulação valem apenas para novas vendas.')}</details>`;
 }
 function ledgers(m){const data=state.record.data;
  const orphan=data.receipts.filter(r=>!m.contracts.some(c=>c.id===r.unitId&&c.contractKey===r.contractKey));
  return `<details class="pc-details" data-section="contributions" id="pc-contributions-section"><summary>Aportes dos sócios <span>${data.contributions.length} lançamento${data.contributions.length===1?'':'s'} · ${data.contributionsReviewed?'conferidos':'a conferir'}</span></summary><form id="pc-aporte" class="pc-form">${field('Sócio','socio','','required maxlength="200"')}${field('Data do aporte realizado','data',day(),'type="date" required max="'+day()+'"')}${amountField('Valor aportado (R$)','valor',null)}${field('Observação','observacao','','maxlength="2000"')}<input type="hidden" name="id"><button class="di-btn primary">Salvar aporte</button><div class="pc-form-feedback" data-pc-feedback aria-live="off"></div></form><label class="pc-check"><input type="checkbox" id="pc-aportes-reviewed" ${data.contributionsReviewed?'checked':''}> Conferi todos os aportes realizados até hoje (inclusive se nenhum).</label>${table(['Sócio','Data','Valor realizado','Observação','Ações'],data.contributions.map(a=>[e(a.socio),date(a.data),money(a.valorCents),e(a.observacao),`<button class="di-btn" data-pc-edit-aporte="${e(a.id)}" type="button">Editar</button> <button class="di-btn" data-pc-delete-aporte="${e(a.id)}" type="button">Excluir</button>`]))}</details>
  <details class="pc-details" data-section="receipts" id="pc-receipts-section"><summary>Recebimentos das vendas <span>${data.receipts.length} ${data.receipts.length===1?'baixa registrada':'baixas registradas'}</span></summary>${note('Registre somente valores efetivamente recebidos. Escolha “final” para manter a separação. A conferência no contrato confirma se o histórico de baixas está completo.')}
  ${orphan.length?'<p class="pc-warning">'+orphan.length+' baixas pertencem a contratos alterados ou inativos. Estão preservadas, mas fora dos totais. Revise cada vínculo antes de reaplicar.</p>':''}
  <form id="pc-receipt" class="pc-form"><label>Unidade<select name="unitId" required><option value="">Selecione</option>${m.contracts.filter(c=>c.coverageComplete).map(c=>`<option value="${e(c.id)}">${e(c.row.u.unidade)}</option>`).join('')}</select></label>${field('Data do recebimento','data',day(),'type="date" required max="'+day()+'"')}${amountField('Valor recebido (R$)','valor',null)}<label>Natureza<select name="natureza"><option value="comum">Durante a obra</option><option value="final">Parcela final (excluída)</option></select></label>${field('Observação','observacao','','maxlength="2000"')}<input type="hidden" name="id"><button class="di-btn primary">Salvar recebimento</button><div class="pc-form-feedback" data-pc-feedback aria-live="off"></div></form>
  ${table(['Unidade','Data','Natureza','Recebido','Observação','Ações'],data.receipts.map(r=>{const c=m.contracts.find(c=>c.id===r.unitId),current=c?.contractKey===r.contractKey;return [e(c?.row.u.unidade||r.unitId),date(r.data),r.natureza==='final'?'Final · excluída':'Durante a obra',money(r.valorCents),e(r.observacao)+(current?'':'<small>Vínculo a revisar; fora dos totais</small>'),`<button type="button" class="di-btn" data-pc-edit-receipt="${e(r.id)}">${current?'Editar':'Revisar vínculo'}</button> <button type="button" class="di-btn" data-pc-delete-receipt="${e(r.id)}">Excluir</button>`];}))}</details>`;
 }
 function legacyNotice(){const info=S.legacyStatus();return info.pending||info.error||info.localError?`<div class="pc-warning"><b>Cópia anterior deste navegador preservada.</b><p>${e(info.error||info.localError||'Há lançamentos locais que ainda não foram transferidos para o sistema. A transferência adiciona registros compatíveis e bloqueia conflitos.')}</p>${info.pending?'<button type="button" class="di-btn" data-pc-migrate>Transferir lançamentos locais</button> <button type="button" class="di-btn" data-pc-export-legacy>Exportar cópia anterior</button>':''}</div>`:info.migrated?'<p class="pc-note">Os lançamentos anteriores deste navegador já foram transferidos para o sistema. A cópia original foi preservada.</p>':'';}
 function contents(){const r=state.record,s=r.data.settings,m=model(),legacy=S.legacyStatus();return `
  <div class="pc-local pc-overview-state"><div><b>${r.revision>0?'Salvo no sistema · revisão '+r.revision:'Previsão inicial · nenhum lançamento salvo'}</b><span>Aportes, comissões, baixas e configurações são compartilhados entre computador e celular, para os perfis autorizados da gestão.${r.updatedAt?' Atualizado em '+e(new Date(r.updatedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))+'.':''}</span><span id="pc-overview-draft" class="pc-draft-notice" ${state.dirty?'':'hidden'}>${state.drafts['pc-settings']?'Simulação não salva':'Edição não salva'}</span></div><button type="button" class="di-btn primary" data-pc-open-section="editing" aria-controls="pc-edit-area">Editar e conferir ↓</button></div>
  <p class="pc-scope">Todo o empreendimento · inclui a loja · filtros das outras abas não se aplicam. <span id="pc-refresh-status">Atualização automática a cada 30 s enquanto esta aba estiver aberta.</span></p>
  <div id="pc-message" role="status" aria-live="polite"></div>
  ${legacy.pending||legacy.error||legacy.localError?'<p class="pc-warning pc-legacy-indicator">Existe uma cópia anterior deste navegador a conferir. Os dados foram preservados. <button type="button" class="di-btn" data-pc-open-section="backup">Conferir cópia ↓</button></p>':''}
  <div id="pc-summary" tabindex="-1">${summary(m)}</div><section id="pc-inventory" class="pc-inventory" tabindex="-1">${inventory(m)}</section>
  <details class="pc-details" data-section="criteria"><summary>Critérios desta previsão</summary><p>Base: vendas confirmadas na revisão atual, valores contratuais em centavos e preço vigente das unidades disponíveis. Aportes são apenas os realizados e conferidos. Permutas já fazem parte da venda e não são somadas duas vezes. A comissão total sai uma única vez. Todas as séries marcadas como finais são excluídas, mesmo se já recebidas.</p><p>Não é fluxo de caixa por data nem apuração de saldo bancário: não desconta gastos de obra realizados. O custo informado representa a necessidade total de recursos. Percentuais futuros não modificam contratos existentes. Recebimentos são decomposição do contratado, nunca receita adicional. As baixas exibidas vêm da Previsão de custo; o módulo Caixa tem registros separados e não é somado automaticamente sem vinculação.</p><p>O registro fica no sistema e é compartilhado entre dispositivos da gestão. Uma gravação só é concluída quando o servidor confirma. Edições simultâneas exigem atualização e conferência; a digitação é preservada. Um contrato alterado exige revisão dos valores; baixas antigas ficam preservadas até serem reavaliadas.</p></details>
  <section id="pc-edit-area" class="pc-edit-area" aria-labelledby="pc-edit-title"><header class="pc-edit-header"><div><p class="pc-eyebrow">LANÇAMENTOS E CONFERÊNCIAS</p><h2 id="pc-edit-title" tabindex="-1">Editar e conferir</h2><p>Ajuste as premissas, confira contratos e registre aportes e recebimentos.</p></div><button type="button" class="di-btn" data-pc-overview>Voltar ao resumo ↑</button></header>
  <nav class="pc-edit-shortcuts" aria-label="Atalhos de edição"><button type="button" class="di-btn" data-pc-open-section="settings" aria-controls="pc-settings-section">Custo e premissas</button><button type="button" class="di-btn" data-pc-open-section="contracts" aria-controls="pc-contracts-section">Contratos</button><button type="button" class="di-btn" data-pc-open-section="contributions" aria-controls="pc-contributions-section">Aportes</button><button type="button" class="di-btn" data-pc-open-section="receipts" aria-controls="pc-receipts-section">Recebimentos</button><button type="button" class="di-btn" data-pc-open-section="backup" aria-controls="pc-backup-section">Backup e recuperação</button></nav><div id="pc-edit-message" aria-live="off"></div>
  <details class="pc-details" data-section="settings" id="pc-settings-section"><summary>Planejar custo e vendas <span class="pc-tag" id="pc-draft">Configuração ${r.revision?'salva':'inicial'}</span></summary><form id="pc-settings" class="pc-settings"><div class="pc-section-title"><div><h2>Custo e premissas para novas vendas</h2><p>Os indicadores recalculam ao editar. Salve para manter esta configuração.</p></div></div><div class="pc-form">${amountField('Custo previsto (R$)','target',s.targetCents)}${field('Durante a obra (%)','payment',percentValue(s.futurePaymentShare),'type="number" min="0" max="100" step="0.01" required')}${field('Parcela final (%)','final',Number((100-s.futurePaymentShare*100).toFixed(2)),'type="number" min="0" max="100" step="0.01" required')}${field('Comissão futura (%)','commission',percentValue(s.futureCommissionRate),'type="number" min="0" max="100" step="0.01" placeholder="Informe, inclusive 0"')}<button class="di-btn primary">Salvar configuração</button></div>${note('A comissão é calculada sobre a venda inteira e descontada da parte durante a obra. Meta bruta = falta cobrir ÷ (percentual durante a obra − comissão). A parcela final não cobre a meta.')}<div class="pc-form-feedback" data-pc-feedback aria-live="off"></div></form></details>
  ${contracts(m)}${ledgers(m)}
  <details class="pc-details" data-section="backup" id="pc-backup-section"><summary>Backup e recuperação <span>Cópias, importação e dados anteriores</span></summary><p class="pc-note">Exporte a revisão confirmada antes de importar uma cópia. A importação substitui os lançamentos e configurações compartilhados da Previsão de custo, em todos os dispositivos.</p><div class="pc-actions"><button type="button" class="di-btn" data-pc-export>Exportar backup</button><button type="button" class="di-btn" data-pc-import>Importar backup</button><input type="file" id="pc-import-file" accept="application/json,.json" hidden></div>${legacyNotice()}</details></section>`;}
 function render(x){
  state=null;
  try{state={x,record:null,selected:new Set(),drafts:{},dirty:false,session:sessionKey(),route:location.hash};return '<div id="pc-root" class="pc-root"><p role="status">Carregando a previsão salva no sistema…</p><div id="pc-message"></div></div>';}
  catch(err){return `<div id="pc-root" class="pc-root"><p role="alert" class="pc-warning">${e(err.message)}</p></div>`;}
 }
 function wire(host,reload){
  const root=host.querySelector('#pc-root');if(!root||!state)return;
  state.root=root;state.reload=reload;
  root.addEventListener('submit',onSubmit);root.addEventListener('input',onInput);root.addEventListener('change',onChange);root.addEventListener('click',onClick);
  if(!refreshTimer)refreshTimer=setInterval(refreshSources,30000);
  const current=state;loadCentral().catch(err=>{if(state===current&&current.root.isConnected)reportError(err);});
 }
 function feedbackNodes(){const nodes=[state.root.querySelector('#pc-message'),state.root.querySelector('#pc-edit-message')];if(state.feedbackForm)nodes.push(state.root.querySelector('#'+state.feedbackForm+' [data-pc-feedback]'));return nodes.filter(Boolean);}
 function message(text,error=false){feedbackNodes().forEach((n,i)=>{n.className=error?'pc-warning':'pc-success';if(i===0)n.setAttribute('role',error?'alert':'status');n.textContent=text;});}
 function repaint(text){
  const open=new Set([...state.root.querySelectorAll('details[open]')].map(n=>n.dataset.section));state.root.innerHTML=contents();state.root.querySelectorAll('details[data-section]').forEach(n=>n.open=open.has(n.dataset.section));
  for(const [id,values] of Object.entries(state.drafts)){const form=state.root.querySelector('#'+id);if(form)for(const [name,value]of Object.entries(values))if(form.elements.namedItem(name))form.elements.namedItem(name).value=value;}
  if(state.drafts['pc-settings']){state.root.querySelector('#pc-draft').textContent='Simulação não salva';calculations();}
  if(state.dirty)state.root.querySelector('#pc-refresh-status').textContent='Atualização automática pausada durante a edição. Salve para retomar.';
  if(text)message(text);
 }
 function reportError(err,current=state){if(!active(current))return;message(err.message,true);if(err.status===409||!current.record)feedbackNodes().forEach(n=>{const b=document.createElement('button');b.type='button';b.className='di-btn';b.dataset.pcReload='';b.textContent=current.record?'Atualizar sem perder a edição':'Tentar carregar novamente';n.append(document.createElement('br'),b);});}
 async function loadCentral(){const current=state;assertActive(current);if(current.saving||current.loading)return;current.loading=true;try{const record=await S.load();if(!active(current)||record.revision<(current.record?.revision||0))return;const initial=!current.record;current.record=record;if(initial){current.root.innerHTML=contents();message(record.revision>0?'Previsão carregada do sistema.':'Conexão confirmada. Salve as premissas e os lançamentos para registrar sua previsão.');}else repaint('Previsão carregada do sistema.');}finally{current.loading=false;}}
 async function persist(action,text,clearForm){
  const current=state;assertActive(current);if(current.loading)throw Error('Aguarde o carregamento dos dados do sistema antes de salvar.');if(current.saving)throw Error('Aguarde a confirmação da gravação atual.');current.saving=true;
  const controls=[...current.root.querySelectorAll('input,select,button'),...document.querySelectorAll('.pc-dialog input,.pc-dialog select,.pc-dialog button')].filter(n=>!n.disabled);controls.forEach(n=>n.disabled=true);
  message('Salvando no sistema… Aguarde a confirmação.');
  try{const record=await action();if(!active(current))return false;current.record=record;if(clearForm)delete current.drafts[clearForm];current.dirty=Object.keys(current.drafts).length>0;repaint(text||'Salvo no sistema. Os outros dispositivos receberão a atualização.');return true;}
  finally{current.saving=false;controls.forEach(n=>{if(n.isConnected)n.disabled=false;});}
 }
 async function save(data,text,clearForm){const current=state,revision=current.record.revision;return persist(()=>S.save(data,revision),text,clearForm);}
 const copy=()=>structuredClone(state.record.data);
 function draft(){const f=state.root.querySelector('#pc-settings');return {targetCents:cents(f.elements.target.value),futurePaymentShare:fraction(f.elements.payment.value),futureCommissionRate:fraction(f.elements.commission.value)};}
 function calculations(){
  const m=model(draft()),sections=['cash','inventory','coverage-issues','sales-composition','shop-inventory'],open=new Set(sections.filter(key=>state.root.querySelector('[data-section="'+key+'"]')?.open));
  const focusedStock=document.activeElement?.getAttribute?.('data-pc-stock');
  state.root.querySelector('#pc-summary').innerHTML=summary(m);state.root.querySelector('#pc-inventory').innerHTML=inventory(m);
  sections.forEach(key=>{const node=state.root.querySelector('[data-section="'+key+'"]');if(node)node.open=open.has(key);});
  if(focusedStock!=null)[...state.root.querySelectorAll('[data-pc-stock]')].find(n=>n.dataset.pcStock===focusedStock)?.focus({preventScroll:true});
 }
 function markDirty(form){if(form)state.drafts[form.getAttribute('id')]=Object.fromEntries(new FormData(form));state.dirty=true;const status=state.root.querySelector('#pc-refresh-status');if(status)status.textContent='Atualização automática pausada durante a edição. Salve para retomar.';const notice=state.root.querySelector('#pc-overview-draft');if(notice){notice.hidden=false;notice.textContent=state.drafts['pc-settings']?'Simulação não salva':'Edição não salva';}}
 function onInput(ev){if(!ev.target.closest('#pc-settings')){if(ev.target.form)markDirty(ev.target.form);return;}const f=ev.target.form;
  if(ev.target.name==='payment'||ev.target.name==='final'){const v=fraction(ev.target.value),other=ev.target.name==='payment'?'final':'payment';f.elements[other].value=v===null?'':Number((100-v*100).toFixed(2));}
  markDirty(f);state.root.querySelector('#pc-draft').textContent='Simulação não salva';calculations();
 }
 function positive(value){const n=cents(value);if(n===null||n<=0)throw Error('Informe um valor positivo no formato 1.234,56.');return n;}
 function actualDate(value){if(!value||value>day())throw Error('Informe uma data de recebimento já realizado, até hoje.');return value;}
 async function onSubmit(ev){
  const f=ev.target,formId=f.getAttribute('id'),owner=state;if(!['pc-settings','pc-aporte','pc-receipt'].includes(formId))return;ev.preventDefault();state.feedbackForm=formId;
  try{
   const data=copy();
   if(formId==='pc-settings'){
    const d=draft();if(d.targetCents===null||d.targetCents<=0)throw Error('Informe um custo previsto maior que zero.');
    if(d.futurePaymentShare===null||d.futurePaymentShare<=0||d.futurePaymentShare>1)throw Error('O percentual durante a obra deve ser maior que 0% e no máximo 100%.');
    if(d.futureCommissionRate!==null&&(d.futureCommissionRate<0||d.futureCommissionRate>=d.futurePaymentShare))throw Error('A comissão deve ser menor que o percentual durante a obra.');
    data.settings=d;await save(data,'Configuração salva no sistema. A meta acompanha as vendas e os aportes conferidos.',formId);
   }else if(formId==='pc-aporte'){
    f.elements.id.value||=uid();markDirty(f);
    const a={id:f.elements.id.value,socio:f.elements.socio.value.trim(),data:actualDate(f.elements.data.value),valorCents:positive(f.elements.valor.value),observacao:f.elements.observacao.value.trim()};
    if(!a.socio)throw Error('Informe o sócio responsável pelo aporte.');
    data.contributions=data.contributions.filter(c=>c.id!==a.id).concat(a);await save(data,'Aporte salvo no sistema. Confirme abaixo se todos os aportes realizados estão registrados.',formId);
   }else{
    const m=model(),c=m.contracts.find(c=>c.id===f.elements.unitId.value&&c.coverageComplete);
    if(!c)throw Error('Conclua a conferência do contrato antes de registrar recebimentos.');
    f.elements.id.value||=uid();markDirty(f);
    const r={id:f.elements.id.value,unitId:c.id,contractKey:c.contractKey,data:actualDate(f.elements.data.value),valorCents:positive(f.elements.valor.value),natureza:f.elements.natureza.value,observacao:f.elements.observacao.value.trim()};
    data.receipts=data.receipts.filter(v=>v.id!==r.id).concat(r);
    const amount=sum(data.receipts.filter(v=>v.unitId===c.id&&v.contractKey===c.contractKey&&v.natureza===r.natureza).map(v=>v.valorCents)),limit=r.natureza==='final'?c.finalCents:c.commonReceivableCents;
    if(amount===null||amount>limit)throw Error('As baixas superam o valor contratado desta natureza. Confira o contrato e os lançamentos.');
    await save(data,'Recebimento salvo no sistema. A conferência do contrato define se o histórico está completo.',formId);
   }
  }catch(err){reportError(err,owner);}
 }
 async function onChange(ev){const owner=state;try{
  if(ev.target.matches('[data-pc-stock]')){ev.target.checked?state.selected.add(ev.target.dataset.pcStock):state.selected.delete(ev.target.dataset.pcStock);calculations();}
  else if(ev.target.id==='pc-aportes-reviewed'){state.feedbackForm='pc-aporte';const checked=ev.target.checked,data=copy();data.contributionsReviewed=checked;try{await save(data);}catch(err){ev.target.checked=!checked;throw err;}}
  else if(ev.target.id==='pc-import-file'){const file=ev.target.files[0];if(file)importFile(file);}
 }catch(err){reportError(err,owner);}}
 function download(json,name){const blob=new Blob([json],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function reveal(node){for(let n=node;n&&n!==state.root;n=n.parentElement)if(n.tagName==='DETAILS')n.open=true;}
 function openSection(name){
  const allowed=['settings','contracts','contributions','receipts','backup'];
  const target=name==='editing'?state.root.querySelector('#pc-edit-area'):allowed.includes(name)?state.root.querySelector('[data-section="'+name+'"]'):null;
  if(!target)return;reveal(target);target.scrollIntoView({block:'start'});const focus=name==='editing'?target.querySelector('#pc-edit-title'):target.querySelector('summary');focus?.focus({preventScroll:true});
 }
 async function onClick(ev){const b=ev.target.closest('button'),owner=state;if(!b)return;try{
  if(b.hasAttribute('data-pc-detail')){detailDialog(b.dataset.pcDetail);return;}
  if(b.hasAttribute('data-pc-open-section')){openSection(b.dataset.pcOpenSection);return;}
  if(b.hasAttribute('data-pc-overview')){const target=state.root.querySelector('#pc-summary');target?.scrollIntoView({block:'start'});target?.focus({preventScroll:true});return;}
  if(b.hasAttribute('data-pc-goal-preset')){const f=state.root.querySelector('#pc-settings');f.elements.payment.value=50;f.elements.final.value=50;f.elements.commission.value=5;markDirty(f);calculations();state.root.querySelector('#pc-draft').textContent='Simulação não salva';return;}
  if(b.hasAttribute('data-pc-reload')){await loadCentral();return;}
  if(b.hasAttribute('data-pc-migrate')){const revision=state.record.revision;await persist(()=>S.migrateLegacy(revision),'Lançamentos anteriores transferidos e salvos no sistema. A cópia local foi preservada.');return;}
  if(b.hasAttribute('data-pc-export-legacy')){const legacy=S.inspectLegacy();if(!legacy.record)throw Error(legacy.error||'Cópia anterior indisponível.');download(S.exportData(legacy.record),'diamond-previsao-copia-anterior-'+day()+'.json');return;}
  if(b.hasAttribute('data-pc-contract'))contractDialog(b.dataset.pcContract);
  if(b.hasAttribute('data-pc-source'))window.DiamondVendaEditor.abrir(b.dataset.pcSource,{onSaved:state.reload});
  if(b.hasAttribute('data-pc-export'))download(S.exportData(state.record),'diamond-previsao-'+day()+'.json');
  if(b.hasAttribute('data-pc-import'))state.root.querySelector('#pc-import-file').click();
  for(const [kind,list,form] of [['aporte','contributions','pc-aporte'],['receipt','receipts','pc-receipt']]){
   const edit=b.getAttribute('data-pc-edit-'+kind),del=b.getAttribute('data-pc-delete-'+kind);
   if(edit){const a=state.record.data[list].find(v=>v.id===edit),f=state.root.querySelector('#'+form);if(!a)return;for(const [k,v]of Object.entries(a))if(f.elements[k])f.elements[k].value=v;f.elements.valor.value=decimal(a.valorCents);state.feedbackForm=form;markDirty(f);reveal(f);f.scrollIntoView({block:'center'});f.querySelector('input,select').focus();message('Editando lançamento. Salve para confirmar; atualizar a página descarta a edição.');}
   if(del){const data=copy();data[list]=data[list].filter(v=>v.id!==del);await save(data,'Lançamento excluído do registro compartilhado no sistema.');}
  }
 }catch(err){reportError(err,owner);}}
 function dialog(title,body){const opener=document.activeElement,owner=state,el=document.createElement('dialog');el.className='pc-dialog';el.dataset.pcRoute=location.hash;el.setAttribute('aria-label',title);el.innerHTML=`<header><h2>${e(title)}</h2><button class="di-btn" type="button" data-close aria-label="Fechar">Fechar</button></header>${body}`;document.body.append(el);el.querySelector('[data-close]').onclick=()=>el.close();el.addEventListener('close',()=>{el.remove();if(active(owner)&&opener?.isConnected)opener.focus({preventScroll:true});});el.showModal();return el;}
 function detailDialog(key){
  assertActive(state);const view=state.presentation,detail=view?.details[key];if(!detail){message('Este detalhamento ainda não está disponível. Atualize os dados e confira novamente.',true);return;}
  const c=view.coverage,partial=detail.complete===false||detail.cents==null,simulationKeys=['inventoryGross','inventoryCoverage','selectionGross','selectionGap','averagePrice','averageContribution','selectionContribution','selectionSurplus','estimatedCount'],isSimulation=simulationKeys.includes(key);
  const percentage=detail.percent!=null?pct(detail.percent)+' do custo previsto':detail.knownPercent!=null?pct(detail.knownPercent)+' do custo · parcial conhecido':'Percentual a conferir';
  const amount=detail.isQuantity?detail.cents==null?'A conferir':String(detail.cents):money(detail.cents);
  const parts=key==='coverage'&&c?`<h3>Composição sem duplicar valores</h3>${table(['Origem','Valor','Efeito na cobertura'],c.decomposition.parts.map(p=>[e(view.details['part-'+p.key]?.title||p.key),money(p.complete?p.cents:p.knownCents),(p.sign<0?'Dedução':'Inclusão')+(p.complete?'':' · parcial identificado')]))}`:'';
  const pending=key==='coverage'&&c&&c.decomposition.pending.length?`<h3>Pendências fora do total conferido</h3><ul class="pc-detail-issues">${c.decomposition.pending.map(p=>`<li>${e(p.id?'Unidade '+(view.model.contracts.find(v=>v.id===p.id)?.row.u.unidade||p.id)+': ':'')}${e(p.reason==='unconfirmed'?'Condições da venda a conferir':p.reason==='coverage_incomplete'?'Composição financeira incompleta':p.reason||'Dados a conferir')}</li>`).join('')}</ul>`:'';
  const calculationContext=['shortfall','requiredGross'].includes(key)?table(['Premissa','Valor'],[['Custo previsto',money(view.model.settings.targetCents)],['Cobertura contratada',money(view.model.totals.coverageCents)],['Falta conferida',money(view.model.totals.shortfallCents)],['Durante a obra',pct(view.model.future.P)],['Comissão futura',pct(view.model.future.C)]]):isSimulation&&c?table(['Premissa da simulação','Valor'],[[c.simulation.partial?'Falta sobre o subtotal conhecido':'Falta conferida',money(c.simulation.gapCents)],['Apartamentos disponíveis',String(c.simulation.availableCount)],['Cobertura do estoque residencial',money(c.simulation.availableContributionCents)],['Cobertura da seleção',money(c.simulation.selection.contributionCents)],['Durante a obra',pct(c.simulation.rates.P)],['Comissão futura',pct(c.simulation.rates.C)]]):'';
  const body=`${isSimulation&&c?.simulation.partial?'<p class="pc-warning">Cenário parcial: a falta usada considera somente o subtotal conhecido da cobertura. Não é uma previsão definitiva.</p>':''}<div class="pc-detail-value"><strong>${e(amount)}</strong>${detail.isQuantity?'':`<span>${e(percentage)}</span>`}</div>${partial?`<p class="pc-warning">Valor a conferir.${detail.knownCents!=null?' Parcial identificado: '+money(detail.knownCents)+'.':''} Informações ausentes não foram tratadas como zero.</p>`:''}${state.drafts['pc-settings']?'<p class="pc-warning">Simulação não salva. Este detalhe usa as premissas em edição.</p>':''}<dl class="pc-detail-context"><dt>Cálculo</dt><dd>${e(detail.formula)}</dd><dt>Fonte</dt><dd>${e(detail.source)}</dd><dt>Base do percentual</dt><dd>Custo previsto: ${money(view.model.settings.targetCents)}. O percentual compara valores com a meta da obra, não representa lucro.</dd></dl>${calculationContext}${parts}${detail.rows.length?`<h3>Registros que compõem o valor</h3><p class="pc-mobile-table-hint">Deslize para ver todas as colunas.</p>${table(['Unidade / origem','Cliente / descrição',e(detail.valueLabel||'Valor'),'Conferência / fonte'],detail.rows.map(r=>[e(r.origin),e(r.description),money(r.cents),e(r.note)]))}`:note('Este indicador resulta das premissas e dos totais apresentados acima.')}${pending}${note(key.startsWith('received')?'Fonte: baixas registradas na Previsão de custo. Recebimentos do módulo Caixa não são importados nem somados automaticamente, pois precisam de vínculo para evitar duplicidade. Recebimentos não são somados novamente à cobertura contratada. Gastos e saídas não são abatidos aqui; este valor não representa caixa disponível.':'Finais ficam fora da cobertura da obra. Percentuais da simulação não alteram condições de vendas já contratadas.')}`;
  const nextLabel=key==='target'?'Editar custo e premissas':['shortfall','requiredGross','estimatedCount'].includes(key)?'Ver simulador':'';
  const owner=state,el=dialog(detail.title,body+(nextLabel?`<footer class="pc-detail-actions"><button type="button" class="di-btn primary" data-pc-detail-action>${nextLabel}</button></footer>`:''));el.classList.add('pc-detail-dialog');
  const next=el.querySelector('[data-pc-detail-action]');if(next)next.onclick=()=>{el.addEventListener('close',()=>{if(!active(owner))return;if(key==='target')openSection('settings');else{const target=owner.root.querySelector('#pc-inventory');target?.scrollIntoView({block:'start'});target?.focus({preventScroll:true});}},{once:true});el.close();};
 }
 function contractDialog(id){const owner=state,expectedRevision=owner.record.revision;assertActive(owner);const m=model(),c=m.contracts.find(c=>c.id===id);if(!c)return;const stored=state.record.data.contracts[id],current=c.manualCurrent;
  const receipts=state.record.data.receipts.filter(r=>r.unitId===id&&r.contractKey===c.contractKey);
  const el=dialog('Conferir unidade '+c.row.u.unidade,`<form id="pc-contract-form"><p>Venda bruta: <b>${money(c.grossCents)}</b> · Entrada: ${money(c.entryCents)} · Permuta: ${money(c.permutaCents)}</p>${!c.compositionComplete?'<p class="pc-warning">A composição não fecha o valor vendido. Revise as condições originais da venda.</p>':''}${stored&&!current?'<p class="pc-warning">O contrato mudou. Confirme novamente a comissão e as séries finais. Baixas da revisão anterior continuam preservadas, fora dos totais.</p>':''}
  ${amountField('Comissão total desta venda (R$)','commission',current?stored.commissionCents:null)}
  <fieldset><legend>Quais séries são parcelas finais?</legend>${c.series.length?c.series.map(p=>`<label class="pc-check"><input type="checkbox" name="finalSeries" value="${p.index}" ${current&&stored.finalSeriesIndices.includes(p.index)?'checked':''}><span>${e(p.description)} · ${p.count} × ${money(p.valueCents)} = ${money(p.totalCents)}</span></label>`).join(''):'<p>Este contrato não tem séries parceladas.</p>'}<label class="pc-check"><input type="checkbox" name="finalReviewed" ${current?'checked':''} required> Conferi as séries finais; nenhuma marcada significa que não há parcela final.</label></fieldset>
  <fieldset><legend>Recebimentos efetivamente realizados</legend><p>Baixas vinculadas a esta revisão: durante a obra <b>${money(sum(receipts.filter(r=>r.natureza==='comum').map(r=>r.valorCents)))}</b> · final <b>${money(sum(receipts.filter(r=>r.natureza==='final').map(r=>r.valorCents)))}</b>.</p><label class="pc-check"><input type="checkbox" name="receiptsReviewed" ${current&&stored.receiptsReviewed?'checked':''}> Todas as baixas recebidas estão registradas, inclusive se nenhum valor foi recebido.</label></fieldset>
  <p role="alert" id="pc-dialog-error"></p><footer><button type="button" class="di-btn" id="pc-original">Condições originais</button><button class="di-btn primary">Salvar conferência</button></footer></form>`);
  el.querySelector('#pc-original').onclick=()=>{if(!active(owner)){el.close();return;}el.close();window.DiamondVendaEditor.abrir(id,{onSaved:owner.reload});};
  el.querySelectorAll('[name="finalSeries"]').forEach(input=>input.addEventListener('change',()=>{
   el.querySelector('[name="receiptsReviewed"]').checked=false;
   el.querySelector('#pc-dialog-error').textContent='A classificação das finais mudou. Revise a natureza das baixas antes de confirmar novamente os recebimentos.';
  }));
  el.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{assertActive(owner);if(owner.record.revision!==expectedRevision)throw Object.assign(Error('A previsão mudou desde a abertura desta conferência.'),{status:409});const f=ev.target,commission=cents(f.elements.commission.value);if(commission===null||commission>c.grossCents)throw Error('Informe a comissão entre zero e o valor bruto da venda.');
   const data=copy();data.contracts[id]={contractKey:c.contractKey,commissionCents:commission,finalSeriesIndices:[...f.querySelectorAll('[name="finalSeries"]:checked')].map(n=>Number(n.value)),receiptsReviewed:f.elements.receiptsReviewed.checked};
   const trial=model(data.settings,data).contracts.find(v=>v.id===id);
   if(data.contracts[id].receiptsReviewed&&!trial.receiptsComplete)throw Error('As baixas excedem a nova classificação. Revise os recebimentos antes de confirmar o histórico.');
   if(await persist(()=>S.save(data,expectedRevision),'Conferência salva no sistema. Os percentuais futuros não alteram esta venda.'))el.close();
  }catch(err){el.querySelector('#pc-dialog-error').textContent=err.message+(err.status===409?' Feche esta janela e atualize os dados antes de conferir novamente.':'');reportError(err,owner);}};
 }
 async function importFile(file){const owner=state,expectedRevision=owner.record.revision;try{
  assertActive(owner);if(file.size>1024*1024)throw Error('O backup excede 1 MB.');const json=await file.text();assertActive(owner);const value=JSON.parse(json);
  const el=dialog('Importar backup no sistema',`<p>Este arquivo substituirá os lançamentos e configurações compartilhados da Previsão de custo, em todos os dispositivos. Exporte o backup atual antes de continuar.</p><p>Arquivo: <b>${e(file.name)}</b> · ${Array.isArray(value.data?.contributions)?value.data.contributions.length:'—'} aportes · ${Array.isArray(value.data?.receipts)?value.data.receipts.length:'—'} baixas.</p><p id="pc-import-error" role="alert"></p><footer><button type="button" class="di-btn primary" id="pc-confirm-import">Substituir pelo backup</button></footer>`);
  el.querySelector('#pc-confirm-import').onclick=async()=>{try{assertActive(owner);if(await persist(()=>S.importData(json,expectedRevision),'Backup importado e salvo no sistema. Confira os vínculos dos contratos atuais.')){owner.drafts={};owner.dirty=false;repaint('Backup importado e salvo no sistema. Confira os vínculos dos contratos atuais.');el.close();}}catch(err){el.querySelector('#pc-import-error').textContent=err.message;reportError(err,owner);}};
 }catch(err){reportError(Error('Não foi possível importar: '+err.message),owner);}finally{if(active(owner)){const input=owner.root.querySelector('#pc-import-file');if(input)input.value='';}}}
 window.addEventListener('storage',ev=>{if(ev.key?.startsWith('dv_previsao_custo_')&&state?.root?.isConnected){if(state.dirty)message('Há dados de outra aba para conferir. Sua digitação foi preservada; salve ou atualize antes de continuar.');else refreshSources();}});
 window.addEventListener('focus',()=>refreshSources());
 window.addEventListener('online',()=>refreshSources());
 window.addEventListener('hashchange',()=>{document.querySelectorAll('.pc-dialog').forEach(el=>{if(el.dataset.pcRoute!==location.hash)el.close();});});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshSources();});
 async function refreshSources(){
  const current=state;
  if(!current?.record||!active(current)||document.hidden||current.refreshing||current.loading||current.saving||current.dirty||document.querySelector('dialog[open]'))return;
  const user=STORE.getUser()?.usuario;current.refreshing=true;
  try{
   const [units,conditions,forecast]=await Promise.allSettled([STORE.api('reservasPainel',{operacao:'listar'}),STORE.api('vendasCondicoes',{operacao:'listar'}),S.load()]);
   if(!active(current)||current.loading||current.saving||current.dirty||document.querySelector('dialog[open]')||STORE.getUser()?.usuario!==user)return;
   const unitsOk=units.status==='fulfilled'&&units.value?.ok!==false&&Array.isArray(units.value?.unidades),conditionsOk=conditions.status==='fulfilled'&&conditions.value?.ok!==false&&Array.isArray(conditions.value?.condicoes);
   const forecastOk=forecast.status==='fulfilled';
   if(forecastOk&&forecast.value.revision>=current.record.revision)current.record=forecast.value;
   const signature=JSON.stringify([unitsOk,conditionsOk,unitsOk?units.value.unidades:null,conditionsOk?conditions.value.condicoes:null,STORE.getCfg(),current.record.revision,forecastOk]);
   if(signature!==current.sourceSignature){
    current.sourceSignature=signature;current.x={...current.x,unitsOk,conditionsOk,unidades:unitsOk?units.value.unidades:[],condicoes:conditionsOk?conditions.value.condicoes:[]};
    current.x.insights=window.DiamondInsights.build({unidades:current.x.unidades,condicoes:current.x.condicoes,leads:current.x.leads,usuarios:STORE.getUsuarios(),cfg:STORE.getCfg()||{},filtros:{}});
    repaint(unitsOk&&conditionsOk&&forecastOk?'Lançamentos, vendas e preços sincronizados com o sistema.':'Não foi possível atualizar todas as fontes. A previsão mostra somente o último registro confirmado; confira a conexão antes de salvar.');
   }
   const status=current.root.querySelector('#pc-refresh-status');if(status)status.textContent=forecastOk?'Última sincronização: '+new Date().toLocaleTimeString('pt-BR')+'.':'Sem sincronização: exibindo a última revisão confirmada.';
  }catch(err){if(state===current&&current.root.isConnected)message('Falha ao atualizar a previsão: '+err.message,true);}
  finally{current.refreshing=false;}
 }
 window.DiamondPrevisao={render,wire,refresh:refreshSources};
})();
